@Override
	public void process(IPayloadContext context)
	{
		context.enqueueWork(() -> {
			ConnectionPoint start = this.connection.start();
			ConnectionPoint end = this.connection.end();
			WireType type = this.connection.type();
			WireLogger.logger.debug(
					"Processing sync for connection from {} to {}, type {}, op {}",
					start, end, type, operation.name()
			);
			Player player = ImmersiveEngineering.proxy.getClientPlayer();
			Level w = player.level();

			GlobalWireNetwork globalNet = GlobalWireNetwork.getNetwork(w);
			Connection connection = this.connection.toConnection();
			if(operation!=ADD&&globalNet.getNullableLocalNet(start)!=null&&globalNet.getNullableLocalNet(end)!=null)
			{
				globalNet.removeConnection(connection);
				removeProxyIfNoWires(start, globalNet);
				removeProxyIfNoWires(end, globalNet);
			}
			if(operation!=REMOVE)
				globalNet.addConnection(connection);
			Set<SectionPos> sectionsToRerender = new ObjectArraySet<>();
			WireUtils.forEachRenderPoint(connection, ($, $2, section) -> sectionsToRerender.add(section));
			for(SectionPos section : sectionsToRerender)
				Minecraft.getInstance().levelRenderer.setSectionDirty(section.x(), section.y(), section.z());
		});
	}

@Override
	public void process(IPayloadContext context)
	{
		Player player = context.player();
		context.enqueueWork(() -> {
			ItemStack held = player.getItemInHand(InteractionHand.OFF_HAND);
			if(fetchSlot >= 0)
			{
				ItemStack s = player.getInventory().items.get(fetchSlot);
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(s);
				if(s.getItem() instanceof IEShieldItem&&upgrades.has(UpgradeEffect.MAGNET))
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, new PrevSlot(fetchSlot));
					s.set(IEDataComponents.UPGRADE_DATA, withSlot);
					player.getInventory().items.set(fetchSlot, held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
			else
			{
				UpgradeData upgrades = UpgradeableToolItem.getUpgradesStatic(held);
				var prevSlot = upgrades.get(UpgradeEffect.MAGNET).prevSlot();
				if(held.getItem() instanceof IEShieldItem&&((IEShieldItem)held.getItem()).getUpgrades(held).has(UpgradeEffect.MAGNET)&&prevSlot.isPresent())
				{
					var withSlot = upgrades.with(UpgradeEffect.MAGNET, PrevSlot.NONE);
					held.set(IEDataComponents.UPGRADE_DATA, withSlot);
					ItemStack s = player.getInventory().items.get(prevSlot.get());
					player.getInventory().items.set(prevSlot.get(), held);
					player.setItemInHand(InteractionHand.OFF_HAND, s);
				}
			}
		});
	}

