private void tryEnqueueProcess(State state, Level level)
	{
		if(state.energy.getEnergyStored() <= 0||state.processor.getQueueSize() >= state.processor.getMaxQueueSize())
			return;
		final FluidStack leftInput = state.tanks.leftInput.getFluid();
		final FluidStack rightInput = state.tanks.rightInput.getFluid();
		if(leftInput.isEmpty()&&rightInput.isEmpty())
			return;
		final ItemStack catalyst = state.inventory.getStackInSlot(SLOT_CATALYST);
		RecipeHolder<RefineryRecipe> recipe = RefineryRecipe.findRecipe(level, leftInput, rightInput, catalyst);
		if(recipe==null)
			return;
		MultiblockProcessInMachine<RefineryRecipe> process = new MultiblockProcessInMachine<>(recipe);
		if(!leftInput.isEmpty()&&!rightInput.isEmpty())
			process.setInputTanks(0, 1);
		else if(!leftInput.isEmpty())
			process.setInputTanks(0);
		else
			process.setInputTanks(1);
		state.processor.addProcessToQueue(process, level, false);
	}

@Nonnull
	@Override
	public ItemStack insertItem(int slot, @Nonnull ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level.get(), state.tank.getFluid(), stack);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stack))
			return stack;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		int inputAmount = 1;
		if(recipe==null)
			process = new BottlingProcess(stack.copy(), stack.copy(), state);
		else
		{
			ItemStack displayStack = recipe.value().getDisplayStack(stack);
			process = new BottlingProcess(recipe, Utils.createNonNullItemStackListFromItemStack(displayStack), state);
			inputAmount = displayStack.getCount();
		}

		if(processor.addProcessToQueue(process, level.get(), simulate))
			stack.shrink(inputAmount);
		return stack;
	}

@Override
	protected ItemStack insert(ItemStack stack, boolean simulate)
	{
		stack = stack.copy();
		RecipeHolder<R> recipe = getRecipeOnInsert.apply(level.get(), stack);
		if(recipe==null)
			return stack;
		ItemStack displayStack;
		if(!doProcessStacking)
		{
			// if process stacking is not allowed, we need to work with exact input quantities
			displayStack = recipe.value().getDisplayStack(stack);
			displayStack = stack.copyWithCount(displayStack.getCount());
		}
		else
			displayStack = stack.copy();
		if(processor.addProcessToQueue(new MultiblockProcessInWorld<>(
				recipe,
				TRANSFORMATION_POINT,
				Utils.createNonNullItemStackListFromItemStack(displayStack)
		), level.get(), simulate, doProcessStacking))
			stack.shrink(displayStack.getCount());
		return stack;
	}

private void enqueueProcesses(State state, Level level)
	{
		// TODO deduplicate with fermenter
		if(state.energy.getEnergyStored() <= 0||state.processor.getQueueSize() >= state.processor.getMaxQueueSize())
			return;
		final int[] usedInvSlots = new int[NUM_INPUT_SLOTS];
		for(MultiblockProcess<?, ?> process : state.processor.getQueue())
			if(process instanceof MultiblockProcessInMachine)
				for(int i : ((MultiblockProcessInMachine<?>)process).getInputSlots())
					usedInvSlots[i]++;

		Integer[] preferredSlots = new Integer[]{0, 1, 2, 3, 4, 5, 6, 7};
		Arrays.sort(preferredSlots, 0, NUM_INPUT_SLOTS, Comparator.comparingInt(arg0 -> usedInvSlots[arg0]));
		for(int slot : preferredSlots)
		{
			ItemStack stack = state.inventory.getStackInSlot(slot);
			if(stack.getCount() <= usedInvSlots[slot])
				continue;
			stack = stack.copy();
			stack.shrink(usedInvSlots[slot]);
			RecipeHolder<SqueezerRecipe> recipe = SqueezerRecipe.findRecipe(level, stack);
			if(recipe!=null)
				state.processor.addProcessToQueue(new MultiblockProcessInMachine<>(recipe, slot), level, false);
		}
	}

private static boolean insertItemToProcess(
			ItemStack stack, boolean simulate, State state, Level rawLevel
	)
	{
		if(state.sawmillProcessQueue.size() >= MAX_PROCESSES)
			return false;
		float dist = 1;
		float minProcessDist = 0.1f;
		SawmillProcess p = null;
		if(state.sawmillProcessQueue.size() > 0)
		{
			p = state.sawmillProcessQueue.get(state.sawmillProcessQueue.size()-1);
			if(p!=null)
			{
				dist = p.getRelativeProcessStep(rawLevel);
				// either it's a different item or we have 3 together already
				if(!ItemStack.isSameItem(stack, p.getInput())||state.combinedLogs > 2)
				{
					if(!simulate)
						state.combinedLogs = 0;
					minProcessDist = 0.5f;
				}
			}
		}
		else if(state.combinedLogs > 0)
			state.combinedLogs = 0;

		if(p!=null&&dist < minProcessDist)
			return false;
		if(!simulate)
		{
			p = new SawmillProcess(stack.copyWithCount(1));
			state.sawmillProcessQueue.add(p);
			state.combinedLogs++;
		}
		stack.shrink(1);
		return true;
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		final IMultiblockLevel level = context.getLevel();
		final Level rawLevel = level.getRawLevel();
		final boolean rsAllowed = state.rsState.isEnabled(context);
		int i = 0;
		Iterator<SawmillProcess> processIterator = state.sawmillProcessQueue.iterator();
		Set<ItemStack> secondaries = new HashSet<>();
		while(rsAllowed&&processIterator.hasNext()&&i++ < MAX_PROCESSES)
		{
			SawmillProcess process = processIterator.next();
			if(process.processStep(rawLevel, state.energy, state.sawblade, secondaries))
				context.markMasterDirty();
			if(process.isProcessFinished())
			{
				state.output.insertOrDrop(process.getCurrentStack(rawLevel, !state.sawblade.isEmpty()).copy(), level);
				processIterator.remove();
				ItemUtils.damageStackableItem(state.sawblade, level.getRawLevel(), IEServerConfig.MACHINES.sawmill_bladeDamage.get());
				context.markDirtyAndSync();
			}
		}
		for(ItemStack output : secondaries)
			state.secondaryOutput.insertOrDrop(output.copy(), level);
		ActiveState renderActive;
		boolean noJobs = state.sawmillProcessQueue.isEmpty();
		boolean hasBlade = !state.sawblade.isEmpty();
		if(state.energy.getEnergyStored() <= 0||!rsAllowed||(noJobs&&!hasBlade))
			renderActive = ActiveState.NOT_RUNNING;
		else if(noJobs)
			renderActive = ActiveState.IDLE_WITH_BLADE;
		else if(hasBlade)
			renderActive = ActiveState.SAWING;
		else
			renderActive = ActiveState.RUNNING_NO_BLADE;
		if(state.active!=renderActive)
		{
			state.active = renderActive;
			context.markDirtyAndSync();
		}
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		final State state = context.getState();
		boolean isRSEnabled = state.rsState.isEnabled(context);
		boolean active = state.processor.tickServer(state, context.getLevel(), isRSEnabled);
		if(active!=state.active)
		{
			state.active = active;
			context.requestMasterBESync();
		}
		if(!context.getLevel().shouldTickModulo(16))
			return;
		if(!isRSEnabled||state.inventory.getStackInSlot(BLUEPRINT_SLOT).isEmpty())
			return;

		List<RecipeHolder<BlueprintCraftingRecipe>> recipes = getAvailableRecipes(context.getLevel().getRawLevel(), state);
		if(state.selectedRecipe >= 0&&state.selectedRecipe < recipes.size())
		{
			RecipeHolder<BlueprintCraftingRecipe> holder = recipes.get(state.selectedRecipe);
			BlueprintCraftingRecipe recipe = holder.value();
			if(!recipe.output.get().isEmpty())
			{
				NonNullList<ItemStack> query = NonNullList.withSize(NUM_INPUT_SLOTS, ItemStack.EMPTY);
				for(int i = 0; i < query.size(); i++)
					query.set(i, state.inventory.getStackInSlot(i+FIRST_INPUT_SLOT));
				int crafted = recipe.getMaxCrafted(query);
				if(crafted > 0&&state.processor.addProcessToQueue(
						new MultiblockProcessInWorld<>(holder, 0.78f, NonNullList.create()),
						context.getLevel().getRawLevel(),
						true
				))
				{
					state.processor.addProcessToQueue(
							new MultiblockProcessInWorld<>(holder, 0.78f, recipe.consumeInputs(query, 1)),
							context.getLevel().getRawLevel(),
							false
					);
					for(int i = 0; i < query.size(); i++)
						state.inventory.setStackInSlot(i+FIRST_INPUT_SLOT, query.get(i));
				}
			}
		}
	}

@Override
	public void onEntityCollision(IMultiblockContext<State> ctx, BlockPos posInMultiblock, Entity collided)
	{
		final Level level = collided.level();
		if(!new BlockPos(0, 1, 1).equals(posInMultiblock)||level.isClientSide)
			return;
		else if(!(collided instanceof ItemEntity)||!collided.isAlive())
			return;
		final State state = ctx.getState();
		final BlockPos absoluteCollisionPos = ctx.getLevel().toAbsolute(posInMultiblock);
		List<Pair<ItemEntity, ItemStack>> itemsOnConveyor = level.getEntitiesOfClass(
				ItemEntity.class, AABB.unitCubeFromLowerCorner(Vec3.atLowerCornerOf(absoluteCollisionPos))
		).stream().map(itemEntity1 -> Pair.of(itemEntity1, itemEntity1.getItem())).toList();
		if(itemsOnConveyor.isEmpty())
			return;

		ItemStack[] stacks = itemsOnConveyor.stream().map(Pair::getSecond).toArray(ItemStack[]::new);
		RecipeHolder<BottlingMachineRecipe> recipe = BottlingMachineRecipe.findRecipe(level, state.tank.getFluid(), stacks);
		if(recipe==null&&!Utils.isFluidRelatedItemStack(stacks[0]))
			return;

		MultiblockProcessInWorld<BottlingMachineRecipe> process;
		NonNullList<ItemStack> displayStacks;
		if(recipe==null)
		{
			ItemStack inputItem = stacks[0].copyWithCount(1);
			displayStacks = Utils.createNonNullItemStackListFromItemStack(inputItem);
			process = new BottlingProcess(inputItem, inputItem.copy(), state);
		}
		else
		{
			displayStacks = recipe.value().getDisplayStacks(stacks);
			process = new BottlingProcess(recipe, displayStacks, state);
		}

		if(state.processor.addProcessToQueue(process, level, false))
			for(ItemStack stack : displayStacks)
				itemsOnConveyor.stream()
						.filter(t -> ItemStack.isSameItemSameComponents(t.getSecond(), stack))
						.findFirst()
						.ifPresent(t -> {
							ItemStack remaining = t.getSecond().copy();
							remaining.shrink(stack.getCount());
							t.getFirst().setItem(remaining);
							if(remaining.isEmpty())
								t.getFirst().discard();
						});
	}

public boolean tickServer(CTX ctx, IMultiblockLevel level, boolean canWork)
	{
		ctx.getEnergy().updateAverage();
		if(!canWork)
			return false;

		int i = 0;
		Iterator<MultiblockProcess<R, CTX>> processIterator = processQueue.iterator();
		boolean tickedAny = false;
		while(processIterator.hasNext()&&i++ < maxProcessPerTick)
		{
			MultiblockProcess<R, CTX> process = processIterator.next();
			if(process.canProcess(ctx, level.getRawLevel()))
			{
				process.doProcessTick(ctx, level);
				tickedAny = true;
			}
			if(process.clearProcess)
			{
				processIterator.remove();
				onQueueChange.run();
			}
		}
		if(tickedAny)
			markDirty.run();
		return tickedAny;
	}

@Override
	public void tickServer()
	{
		tickCommon();
		if(level.getGameTime()%64==((getBlockPos().getX()^getBlockPos().getZ())&63))
			markContainingBlockForUpdate(null);

		int energy = IEServerConfig.MACHINES.turret_consumption.get();
		if(isRSPowered()^config.redstoneControlInverted)
		{
			if(energyStorage.extractEnergy(energy, true)==energy)
			{
				energyStorage.extractEnergy(energy, false);
				if(target==null||!target.isAlive()||level.getEntity(target.getId())==null||target.getHealth() <= 0||!canShootEntity(target))
				{
					target = getTarget();
					if(target!=null)
					{
						this.setChanged();
						markContainingBlockForUpdate(null);
					}
				}

				//has target, Redstone control check and has power+ammo
				if(target!=null&&canActivate())
				{
					tick++;
					int chargeup = getChargeupTicks();
					if(tick==chargeup)
						this.activate();
					else if(tick > chargeup)
					{
						if(loopActivation())
							this.activate();
						else if(tick==chargeup+getActiveTicks())
							tick = 0;
					}
				}
				else
					tick = 0;
			}
		}
		else if(target!=null)
			target = null;
	}

@Override
	public void tickServer()
	{
		if(active)
		{
			if(activeTicks%160==0) // sound refreshes after 8 seconds
				getLevelNonnull().playSound(null, getPosition(), this.sound.sound.value(), SoundSource.BLOCKS, 4, 1);
			if(activeTicks%80==0) // entities update after 4 seconds
			{
				AABB aabb = new AABB(getPosition()).inflate(RADIUS);
				List<LivingEntity> nearbyEntities = getLevelNonnull().getEntitiesOfClass(LivingEntity.class, aabb, entity -> entity.isAlive()&&!entity.isRemoved());
				nearbyEntities.forEach(entity -> {
					// hear the bell
					entity.getBrain().setMemory(MemoryModuleType.HEARD_BELL_TIME, getLevelNonnull().getGameTime());
					// make raiders glow
					if(entity.getType().is(EntityTypeTags.RAIDERS))
						entity.addEffect(new MobEffectInstance(MobEffects.GLOWING, 80));
				});
			}
			activeTicks++;
		}
		else if(activeTicks > 0)
			activeTicks = 0;
	}

public static boolean markEntityAsHandled(Entity e)
	{
		MutableLong currentTick;
		IntSet entitiesHandledInCurrentTick;
		if(e.level().isClientSide)
		{
			currentTick = currentTickClient;
			entitiesHandledInCurrentTick = entitiesHandledInCurrentTickClient;
		}
		else
		{
			currentTick = currentTickServer;
			entitiesHandledInCurrentTick = entitiesHandledInCurrentTickServer;
		}
		long now = e.level().getGameTime();
		if(now!=currentTick.getValue())
		{
			currentTick.setValue(now);
			entitiesHandledInCurrentTick.clear();
		}
		return entitiesHandledInCurrentTick.add(e.getId());
	}

@Override
	public void tickServer()
	{
		if(level.getGameTime()%8!=0||!isActive())
			return;
		IItemHandler outputHandler = output.getCapability();
		if(outputHandler!=null)
		{
			boolean matched = true;
			if(this.batchMode==BatchMode.ALL)
			{
				for(int slot = 0; slot < NUM_SLOTS; slot++)
					if(!this.filters.get(slot).isEmpty())
						matched &= isFilterMatched(slot);
			}
			if(matched)
			{
				boolean anySent = false;
				for(int slot = 0; slot < NUM_SLOTS; slot++)
				{
					ItemStack filterStack = this.filters.get(slot);
					if(filterStack.isEmpty())
						continue;
					if(this.batchMode==BatchMode.ALL||isFilterMatched(slot))
					{
						ItemStack outStack = buffers.get(slot);
						int outSize = filterStack.getCount();
						ItemStack stack = outStack.copyWithCount(outSize);
						stack = ItemHandlerHelper.insertItem(outputHandler, stack, false);
						if(!stack.isEmpty())
							outSize -= stack.getCount();
						outStack.shrink(outSize);
						if(outStack.getCount() <= 0)
							this.buffers.set(slot, ItemStack.EMPTY);
						anySent = true;
					}
				}
				if(anySent)
					redstoneCap.markDirty();
			}
		}
	}

@Override
	public void tickServer(IMultiblockContext<State> context)
	{
		State state = context.getState();
		IMultiblockLevel level = context.getLevel();
		final Level rawLevel = context.getLevel().getRawLevel();
		if(rawLevel instanceof ServerLevel serverLevel)
		{
			BlockPos broadcastPos = level.toAbsolute(BROADCAST_POS);
			// update the maximum range if it's undefined or every ~ 7 minutes
			if(state.rangeInChunks < 0||serverLevel.getGameTime()%8192==((broadcastPos.getX()^broadcastPos.getZ())&8191))
			{
				int maxRange = calculateMaxRange(serverLevel, broadcastPos, 4);
				state.rangeInChunks = maxRange;
			}

			// fetch the wireless handler for this world
			WirelessRedstoneHandler handler = WirelessRedstoneHandler.getHandler(serverLevel);

			// consume energy and set active state
			int consumed = IEServerConfig.MACHINES.radio_tower_consumption.get();
			int extracted = state.energy.extractEnergy(consumed, false);
			final boolean prevActive = state.active;
			state.active = extracted >= consumed;
			// if active state changed, notify the network
			if(state.active!=prevActive)
				state.markSendAndReceiveDirty();

			// register with handler if not yet done
			if(!handler.isRegistered(broadcastPos, context.getState()))
				handler.register(broadcastPos, context.getState());

			// if the sending signal has changed, notify other components
			if(state.sendingDirty)
			{
				handler.notifyComponents(broadcastPos, state);
				state.sendingDirty = false;
			}
			// if the network has changed, fetch new signal
			if(state.receivingDirty)
			{
				state.receivedSignals = state.isActive()?handler.fetchSignals(broadcastPos, state): new byte[16];
				state.bundleConnection.markDirty();
				state.receivingDirty = false;
			}
		}
	}

public boolean addProcessToQueue(
			MultiblockProcess<R, CTX> process, Level level, boolean simulate, boolean addToPrevious
	)
	{
		if(addToPrevious&&process instanceof MultiblockProcessInWorld)
		{
			// Pattern variables look fine in IntelliJ, but cause the "real" compiler to complain. Probably related to
			// the CTX type parameter
			@SuppressWarnings("PatternVariableCanBeUsed") final MultiblockProcessInWorld<R> newProcess = (MultiblockProcessInWorld<R>)process;
			for(MultiblockProcess<R, CTX> curr : processQueue)
				if(curr instanceof MultiblockProcessInWorld&&process.getRecipeId().equals(curr.getRecipeId()))
				{
					boolean canStack = true;
					final MultiblockProcessInWorld<R> existingProcess = (MultiblockProcessInWorld<R>)curr;
					for(ItemStack old : existingProcess.inputItems)
					{
						for(ItemStack in : newProcess.inputItems)
							if(ItemStack.isSameItemSameComponents(old, in))
								if(old.getCount()+in.getCount() > old.getMaxStackSize())
								{
									canStack = false;
									break;
								}
						if(!canStack)
							break;
					}
					if(canStack)
					{
						if(!simulate)
							for(ItemStack old : existingProcess.inputItems)
							{
								for(ItemStack in : newProcess.inputItems)
									if(ItemStack.isSameItemSameComponents(old, in))
									{
										old.grow(in.getCount());
										break;
									}
							}
						return true;
					}
				}
		}
		if(maxQueueLength < 0||processQueue.size() < maxQueueLength)
		{
			if(!processQueue.isEmpty())
			{
				MultiblockProcess<R, CTX> previousProcess = processQueue.get(processQueue.size()-1);
				final int maxTime = previousProcess.getMaxTicks(level);
				float dist = previousProcess.processTick/(float)maxTime;
				if(dist < minDelayAfter.applyAsDouble(maxTime))
					return false;
			}

			if(!simulate)
				processQueue.add(process);
			markDirty.run();
			onQueueChange.run();
			return true;
		}
		return false;
	}
